"""Load explanation and 22 C tank/inlet sensitivity. No new motor map or CFD."""
from pathlib import Path
import json,math
from CoolProp.CoolProp import PropsSI
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch,Polygon,Rectangle
OUT=Path(__file__).resolve().parents[1]/'results'

def build():
    cp=1006.;mass=.0194;power=840.;ua=10.073720659304273;ambient=30.;tin=22.;p_atm=101325.;retention=math.exp(-ua/(mass*cp));drop=power/(mass*cp);tm=tin-drop;tn=ambient+(tm-ambient)*retention
    h=PropsSI('H','P',p_atm+200e5,'T',tin+273.15,'Air');tr=PropsSI('T','P',p_atm+6.3e5,'H',h,'Air')-273.15
    cases=[]
    for tank_p in [200,100,50,20]:
        hh=PropsSI('H','P',p_atm+tank_p*1e5,'T',295.15,'Air');tt=PropsSI('T','P',p_atm+6.3e5,'H',hh,'Air')-273.15;cases.append(dict(tank_bar_g=tank_p,tank_c=22,heat_free_throttle_outlet_c=tt))
    result=dict(status='Conditional first-law and real-air sensitivity; no new CFD or motor-map validation',inputs=dict(tank_c=22,tank_bar_g=200,motor_running_bar_g=6.3,motor_inlet_c_in_conditional_case=22,ambient_c=ambient,loaded_mass_g_s=mass*1000,shaft_load_w=power,loaded_rpm=1270,free_rpm=2400,cp_j_kg_k=cp,path_ua_w_k=ua,path_retention=retention),conditional_motor_inlet22=dict(motor_temperature_drop_k=drop,motor_exhaust_c=tm,nozzle_c=tn,nozzle_drop_vs_30c_ambient_k=ambient-tn,source_sensible_w=mass*cp*(ambient-tn),required_load_torque_nm=power/(1270*2*math.pi/60)),tank22_real_throttle=cases,no_load=dict(external_shaft_work_w=0,nominal_free_rpm=2400,mass_flow_g_s=None,exhaust_c=None,reason='Free-running airflow and motor heat transfer are not published in the available point data. No external 840 W shaft extraction. Startup stores rotational energy; internal losses and casing heat transfer may still alter exhaust temperature.'),equations=dict(rotor='I domega/dt = torque_air - torque_friction - torque_load',shaft='Wshaft = torque_load * omega',energy='T0_out = T0_in - (Wshaft - Q_into_motor)/(mdot cp), negligible potential-energy change',flow='mdot = rho A U; mdot depends on inlet pressure, exhaust pressure, speed, temperature and leakage',cold_path='Tout = Ta + (Tmotor - Ta) exp[-UA/(mdot cp)]',regulator='hout=hin only for negligible heat/shaft-work/kinetic changes'),limits=['22 C in the tank is not automatically 22 C at the motor inlet','At a hypothetical heat-free initial 200-to-6.3 bar throttle, real-air EOS gives about -11.8 C; walls, hoses and blowdown change this','Do not extrapolate the 840 W / 19.4 g/s motor pair to that subzero inlet without a supplier map or test','The motor-inlet22 result assumes sustained catalogue power/flow and zero net heat into the motor','No-load means zero external shaft work, not necessarily exactly zero exhaust cooling; regulator cooling and casing heat remain possible','The 19.4 g/s value is already the loaded catalogue-point conversion; it is not free-running airflow','Too much load can stall the rotor; shaft power then tends to zero even if leakage continues','Path UA is inherited and unmeasured; no steady or startup thermal guarantee','Bulk energy calculation uses stagnation temperature; high-speed port static temperature may differ before diffuser recovery','Product page lists 7 bar maximum; manual says 6.3 bar or nameplate. Keep 6.3 bar running target and confirm the nameplate/pressure-reduction package','Existing saved CFD remains at 4.313/10.281 C source. No CFD at -0.461 C was run'],references=[dict(title='LZB46 product ratings',url='https://www.atlascopco.com/en-us/itba/products/air-motors/lzb46-rl-a025-11-sku8411047249'),dict(title='Atlas Copco B4770001 manual: no-load hotspots, load and speed',url='https://picontent.atlascopco.com/cont/external/dir/0e/410867083_B4770001_html5_external/en-US/print-section.html?section=all'),dict(title='CoolProp Air EOS',url='https://coolprop.org/fluid_properties/fluids/Air.html')])
    checks=[]
    def check(name,b):assert b,name;checks.append(name)
    check('Loaded energy balance',abs(mass*cp*(tin-tm)-power)<1e-9)
    check('Path warms motor exhaust toward 30 C',tm<tn<ambient)
    check('22 C motor inlet drop is 43.0407 K',abs(drop-43.040724723822017)<1e-10)
    check('Zero path UA would preserve exhaust',ambient+(tm-ambient)*math.exp(0)==tm)
    check('Half load at fixed mass halves enthalpy extraction',abs((420/(mass*cp))*2-drop)<1e-10)
    check('No-load flow is not invented',result['no_load']['mass_flow_g_s'] is None)
    check('Initial real-air throttle differs from tank temperature',tr<22)
    check('Throttle conserves specific enthalpy',abs(PropsSI('H','P',p_atm+6.3e5,'T',tr+273.15,'Air')-h)<1e-4)
    (OUT/'load22-calculations.json').write_text(json.dumps(result,indent=2));(OUT/'load22-validation.json').write_text(json.dumps(dict(status='passed',checks=len(checks),items=checks,scope='Algebra/EOS only; no new CFD, Lean or hardware validation'),indent=2))
    # Engineering schematic, not an assembly drawing or a performance illustration.
    fig,ax=plt.subplots(figsize=(14,5.6));fig.patch.set_facecolor('white');ax.set(xlim=(0,14),ylim=(0,5.6));ax.axis('off');ink='#162b35';air='#007b88';shaft='#b46b16'
    def box(x,y,w,h,label,fc='#f1f4f4',edge=ink,fs=11):
        ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.06,rounding_size=.1',facecolor=fc,edgecolor=edge,lw=1.5));ax.text(x+w/2,y+h/2,label,ha='center',va='center',fontsize=fs,color=ink)
    def arrow(a,b,c=air,lw=2):ax.annotate('',xy=b,xytext=a,arrowprops=dict(arrowstyle='-|>',color=c,lw=lw))
    ax.text(.2,5.18,'One motor: the air path and shaft load are separate',fontsize=17,weight='bold',color=ink)
    box(.45,2.4,1.1,2.0,'SCUBA\nTANK\n\n200 bar\n22°C',fs=11);ax.add_patch(Rectangle((.8,4.4),.4,.2,facecolor=ink));arrow((1.55,3.45),(2.4,3.45));box(2.45,2.9,2,1.1,'Rated pressure\nreducer + protection',fs=10.5);arrow((4.5,3.45),(5.2,3.45));box(5.25,3.1,.65,.7,'Valve',fs=9);arrow((5.95,3.45),(6.45,3.45));box(6.5,2.85,1.9,1.2,'LZB46 MOTOR\n6.3 bar g running\n1270 rpm loaded',fs=10.5)
    ax.text(4.6,4.35,'Regulator + hose set motor inlet temperature. Measure it here.',ha='center',fontsize=10,color=ink);ax.annotate('',xy=(6.38,3.45),xytext=(6.3,4.15),arrowprops=dict(arrowstyle='->',lw=1,color='#6c7a80'))
    arrow((8.45,3.45),(10.2,3.45));ax.text(9.3,3.8,'Short insulated\nexhaust hose',ha='center',fontsize=10,color=air);ax.add_patch(Polygon([[10.25,3.25],[10.25,3.65],[11.45,3.85],[11.45,3.05]],closed=True,facecolor='#e9f1f3',edgecolor=ink,lw=1.5));ax.text(10.85,2.75,'Engineered nozzle',ha='center',fontsize=10,color=ink);arrow((11.55,3.45),(13.2,3.45));ax.text(12.45,3.85,'20–50 cm\nfrom nozzle',ha='center',fontsize=11,color=air)
    ax.text(8.8,4.65,'AIR: nominal 19.4 g/s at the loaded point',ha='center',fontsize=11,color=air)
    arrow((7.45,2.79),(7.45,1.88),shaft,3);ax.text(7.7,2.3,'Guarded shaft\ncoupling',ha='left',va='center',fontsize=10,color=shaft);box(5.95,.65,3,1.15,'Controlled brake OR\ngenerator + load bank\n840 W mechanical / ~6.3 N·m',fc='#fcf4e8',edge=shaft,fs=11);arrow((9.05,1.2),(11.15,1.2),shaft);ax.text(11.35,1.2,'Reject load heat\naway from cold air',ha='left',va='center',fontsize=11,color=shaft)
    ax.text(.35,.18,'Concept layout only. No air flows through the shaft load. Rated reducer, motor map, low-temperature limits and fittings need qualification.',fontsize=9,color='#46585f')
    fig.tight_layout(pad=.6);fig.savefig(OUT/'shaft-load-configuration.svg');fig.savefig(OUT/'shaft-load-configuration.png',dpi=140);plt.close(fig)
    section=f'''<details class="card compact-details" id="shaft-load-22"><summary>Shaft load and 22°C tank: sketch / calculation</summary><p><strong>The load acts on the rotating shaft, not as a valve in the exhaust.</strong> Added load lowers speed and changes airflow. Our 19.4 g/s is already the loaded 840 W / 1270 rpm catalogue-point conversion. Free-running speed is about 2400 rpm; unloaded flow and exhaust temperature are not established here. Excess load can stall the motor and eliminate shaft power.</p><img src="shaft-load-configuration.svg" style="width:100%;height:auto;background:white" alt="Separate regulated air path and motor shaft connected to an external brake or generator load"><div class="formula-equation">Wshaft = torque × angular speed<br>Tmotor ≈ Tin − (Wshaft − Qinto_motor)/(ṁ cp)<br>840/(0.0194 × 1006) = 43.04 K</div><p><strong>If air entering the motor is 22°C:</strong> conditional exhaust = {tm:.2f}°C. The same assumed path UA and 30°C ambient give {tn:.2f}°C at the nozzle. This is a calculation, not a measured guarantee.</p><p class="note">22°C in the tank does not fix motor inlet temperature. At initial 200 bar, an ideal heat-free real-air throttle to 6.3 bar gives {tr:.2f}°C before hose warming. Do not apply the fixed motor power/flow pair to this subzero state without a motor map/test. Tank pressure and temperature also change during discharge.</p><p class="note">With no external load, external shaft work tends to zero after spin-up. The model’s sustained 840 W extraction disappears. Regulator cooling, casing heat transfer and local static-temperature effects can remain; no exact unloaded temperature or g/s is claimed. The manufacturer's manual notes high no-load housing hotspots; this is not an exhaust-temperature rating.</p><p class="note">Saved CFD below remains at 4.31°C / 10.28°C sources. No −0.46°C-source CFD was generated.</p><div class="links"><a href="shaft-load-configuration.png" download>Sketch PNG</a><a href="shaft-load-configuration.svg" download>Editable SVG</a><a href="load22-calculations.json">22°C calculations / sources</a><a href="load22-validation.json">8 numerical checks</a></div></details>'''
    (OUT/'load22-section.html').write_text(section);return section
if __name__=='__main__':build()
